sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var savedFixture = gs.getProperty('x_fed_compliance.test_fixture_scope_grants', '');
  try {
    gs.setProperty('x_fed_compliance.test_fixture_scope_grants', JSON.stringify({
      appRoleAssignments: ['Policy.Read.All', 'Directory.ReadWrite.All'],
      delegatedScopes: []
    }));
    var gate = new x_fed_compliance.ComplianceGate();
    var verdict = gate._checkWriteScope();
    if (verdict !== 'holds-write') {
      stepResult.setFailed("expected 'holds-write' when Directory.ReadWrite.All is granted, got '" + verdict + "'");
      return;
    }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_compliance.test_fixture_scope_grants', savedFixture);
  }
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var savedFixture = gs.getProperty('x_fed_compliance.test_fixture_scope_grants', '');
  try {
    gs.setProperty('x_fed_compliance.test_fixture_scope_grants', JSON.stringify({
      appRoleAssignments: ['Directory.Read.All'],
      delegatedScopes: ['User.Read', 'Mail.ReadWrite']
    }));
    var gate = new x_fed_compliance.ComplianceGate();
    var verdict = gate._checkWriteScope();
    if (verdict !== 'holds-write') {
      stepResult.setFailed("expected 'holds-write' when a delegated scope (Mail.ReadWrite) is write-shaped, got '" + verdict + "'");
      return;
    }
    stepResult.setSuccess();
  } finally {
    gs.setProperty('x_fed_compliance.test_fixture_scope_grants', savedFixture);
  }
})(outputs, steps, stepResult);
